(6901414, 1040477, 65234, '<td valign="top">Uh-oh!!  Very scary doll and creepy lighting, besides.</td>', 'Uh-oh!!  Very scary doll and creepy lighting, besides.', '2012-11-07 21:20:07.000000', NULL, 1),
