(6907912, 1040368, 15574, '<td valign="top">Wish this would have done better. Love Dexter and thought the shot was great. My only complaint is Dave''s right hand up. Feels too staged and not conservative like Dexter''s actions. Good stuff though Cory.</td>', 'Wish this would have done better. Love Dexter and thought the shot was great. My only complaint is Dave''s right hand up. Feels too staged and not conservative like Dexter''s actions. Good stuff though Cory.', '2012-11-17 00:46:46.000000', NULL, 0),
(6908074, 1040472, 52549, '<td valign="top">So spooky, but brilliantly done. Excellent work, Samantha.</td>', 'So spooky, but brilliantly done. Excellent work, Samantha.', '2012-11-17 13:37:02.000000', NULL, 0),
(6908950, 1040452, 108580, '<td valign="top">WD on your blue! And welcome to my world (of bird photography), especially BiF (Bird in Flight). Fish Eagles in bright sunlight with "baited" fish is not that difficult as totally random flight patterns or skittish birds :) Hope to see more 10''s from you on my next challenge entry :)</td>', 'WD on your blue! And welcome to my world (of bird photography), especially BiF (Bird in Flight). Fish Eagles in bright sunlight with "baited" fish is not that difficult as totally random flight patterns or skittish birds :) Hope to see more 10''s from you on my next challenge entry :)', '2012-11-19 07:51:22.000000', NULL, 0),
(6908951, 1040472, 108580, '<td valign="top">Excellent creation. WD. You live in Amityville?</td>', 'Excellent creation. WD. You live in Amityville?', '2012-11-19 07:53:50.000000', NULL, 0),
